// Grafana webhook gövdesini okunur Türkçe mesajlara çevirir (her alarm için bir öğe).
const body = $input.first().json.body ?? $input.first().json;
const SEV = {
  kritik: { icon: '🔴', label: 'KRİTİK' },
  uyari:  { icon: '🟠', label: 'UYARI' },
  bilgi:  { icon: '🔵', label: 'BİLGİ' },
};
const fmtTime = (iso) => new Date(iso).toLocaleString('tr-TR', { timeZone: 'Europe/Istanbul' });

return (body.alerts ?? []).map((a) => {
  const sev = SEV[a.labels?.onem] ?? { icon: '⚪', label: (a.labels?.onem ?? '').toUpperCase() };
  const resolved = a.status === 'resolved';
  const title = resolved
    ? `✅ Düzeldi · ${a.labels?.alertname ?? 'Alarm'}`
    : `${sev.icon} ${sev.label} · ${a.labels?.alertname ?? 'Alarm'}`;
  const lines = [
    title,
    a.annotations?.summary ?? '',
    resolved ? '' : (a.annotations?.description ?? ''),
    `🕒 ${fmtTime(resolved ? a.endsAt : a.startsAt)}`,
    a.dashboardURL || a.generatorURL ? `🔗 ${a.dashboardURL || a.generatorURL}` : '',
  ].filter(Boolean);
  return {
    json: {
      durum: resolved ? 'duzeldi' : 'tetiklendi',
      onem: a.labels?.onem ?? '',
      baslik: title,
      mesaj: lines.join('\n'),
      alarm: a.labels?.alertname ?? '',
      zaman: resolved ? a.endsAt : a.startsAt,
      ozet: a.annotations?.summary ?? '',
      aciklama: a.annotations?.description ?? '',
    },
  };
});

// Hangi alarmlarda telefonla aranacağına karar verir ve ElevenLabs arama isteğini hazırlar.
// ====== AYARLAR: değerleri n8n içinde doldurun (bu dosyayı gerçek değerlerle git'e göndermeyin) ======
const AYAR = {
  agentId: 'AGENT_ID_BURAYA',                  // ElevenLabs → agent ayarları (agent_...)
  telefonNumarasiId: 'PHONE_NUMBER_ID_BURAYA', // ElevenLabs → Phone Numbers → numara kimliği (phnum_...)
  aranacakNumara: '+90XXXXXXXXXX',              // aranacak cep telefonu, +90 ile başlayan
  kullaniciAdi: 'ADINIZ',                       // agent sizi bu adla selamlar
  hat: 'twilio',                                // numara Twilio'dan ise 'twilio', SIP trunk ise 'sip'
  arananOnemler: ['kritik'],                    // 'uyari' eklenirse uyarılarda da arar
  ayniAlarmTekrarDk: 60,                        // aynı alarm için en erken kaç dakika sonra tekrar aransın
};
// ======================================================================================================

const store = $getWorkflowStaticData('global');  // sadece aktif (production) çalışmalarda kalıcıdır
store.sonArama = store.sonArama ?? {};
const now = Date.now();

const adaylar = $input.all().map((i) => i.json)
  .filter((a) => a.durum === 'tetiklendi' && AYAR.arananOnemler.includes(a.onem))
  .filter((a) => !(store.sonArama[a.alarm] && now - store.sonArama[a.alarm] < AYAR.ayniAlarmTekrarDk * 60000));

// Aynı alarm tek mesajda birden çok kez gelebilir: alarm adına göre tekilleştir
const alarmlar = [...new Map(adaylar.map((a) => [a.alarm, a])).values()];
if (alarmlar.length === 0) return [];  // aranacak bir şey yok, akış burada biter

for (const a of alarmlar) store.sonArama[a.alarm] = now;
for (const [k, t] of Object.entries(store.sonArama)) if (now - t > 24 * 3600000) delete store.sonArama[k];

// Telefonda okunacak metin: emoji ve bağlantıları çıkar
const temizle = (s) => String(s ?? '')
  .replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}]/gu, '')
  .replace(/https?:\/\/\S+/g, '')
  .replace(/\s+/g, ' ').trim();
const saat = (iso) => new Date(iso).toLocaleString('tr-TR', {
  timeZone: 'Europe/Istanbul', day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit',
});

const ilk = alarmlar[0];
const istek = {
  agent_id: AYAR.agentId,
  agent_phone_number_id: AYAR.telefonNumarasiId,
  to_number: AYAR.aranacakNumara,
  conversation_initiation_client_data: {
    dynamic_variables: {
      kullanici_adi: AYAR.kullaniciAdi,
      alarm_adi: alarmlar.length === 1 ? ilk.alarm : `${ilk.alarm} ve ${alarmlar.length - 1} alarm daha`,
      alarm_zamani: saat(ilk.zaman),
      alarm_detayi: alarmlar.map((a) => `${a.alarm}: ${temizle(a.ozet)} ${temizle(a.aciklama)}`.trim())
        .join(' | ').slice(0, 1500),
      onem_seviyesi: ilk.onem,
    },
  },
};
const url = AYAR.hat === 'sip'
  ? 'https://api.elevenlabs.io/v1/convai/sip-trunk/outbound-call'
  : 'https://api.elevenlabs.io/v1/convai/twilio/outbound-call';

return [{ json: { url, istek, alarmlar: alarmlar.map((a) => a.alarm) } }];

// Arama başlatılamadı: bekleme kilidini kaldır ki Grafana bir sonraki hatırlatmada tekrar arayabilsin.
const store = $getWorkflowStaticData('global');
const alarmlar = $('Arama kararı').first().json.alarmlar ?? [];
for (const a of alarmlar) delete store.sonArama?.[a];
return [{ json: { arama: 'başarısız', alarmlar, hata: $input.first().json.error ?? $input.first().json } }];
